CREATE TYPE "employee_status" AS ENUM (
  'dang_lam_viec',
  'da_nghi_viec'
);

CREATE TYPE "leave_status" AS ENUM (
  'cho_xac_thuc',
  'da_duoc_duyet',
  'bi_tu_choi'
);

CREATE TYPE "project_status" AS ENUM (
  'dang_thuc_hien',
  'hoan_thanh'
);

CREATE TYPE "task_status" AS ENUM (
  'can_lam',
  'dang_lam',
  'xong'
);

CREATE TYPE "task_priority" AS ENUM (
  'thap',
  'trung_binh',
  'cao'
);

CREATE TABLE "users" (
  "user_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar,
  "password" varchar,
  "role" varchar,
  "created_at" timestamp
);

CREATE TABLE "departments" (
  "department_id" integer PRIMARY KEY,
  "department_name" varchar,
  "managment" varchar,
  "category" varchar,
  "created_at" timestamp
);

CREATE TABLE "employees" (
  "employee_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" integer UNIQUE NOT NULL,
  "department_id" integer NOT NULL,
  "fullname" varchar,
  "email" varchar,
  "phone_number" varchar,
  "birthday" varchar,
  "manage_by" varchar,
  "position" varchar,
  "start_date" date,
  "status" employee_status DEFAULT 'dang_lam_viec',
  "created_at" timestamp
);

CREATE TABLE "attendances" (
  "attendances_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" integer NOT NULL,
  "date" date,
  "check_in" time,
  "check_out" time,
  "created_at" timestamp
);

CREATE TABLE "Day_off_requests" (
  "Day_off_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_send_id" integer NOT NULL,
  "employee_receive_id" integer NOT NULL,
  "start_date" date,
  "end_date" date,
  "reason" text,
  "status" leave_status DEFAULT 'cho_xac_thuc',
  "created_at" timestamp
);

CREATE TABLE "projects" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(20) UNIQUE NOT NULL,
  "name" varchar(200) NOT NULL,
  "description" text,
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "status" project_status NOT NULL DEFAULT 'dang_thuc_hien',
  "manager_id" int NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "project_members" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "employee_id" int NOT NULL,
  "project_id" int NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "tasks" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" int NOT NULL,
  "title" varchar(200) NOT NULL,
  "description" text,
  "assignee_id" int NOT NULL,
  "created_by" int NOT NULL,
  "due_date" date NOT NULL,
  "priority" task_priority NOT NULL DEFAULT 'trung_binh',
  "status" task_status NOT NULL DEFAULT 'can_lam',
  "created_at" timestamp NOT NULL DEFAULT (now()),
  "updated_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "task_comments" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "author_id" int NOT NULL,
  "task_id" int NOT NULL,
  "content" text NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (now())
);

CREATE UNIQUE INDEX ON "project_members" ("project_id", "employee_id");

CREATE INDEX ON "tasks" ("project_id", "status");

CREATE INDEX ON "tasks" ("assignee_id");

COMMENT ON TABLE "projects" IS 'Dự án. Khi tạo dự án, hệ thống cũng thêm manager vào project_members.';

COMMENT ON COLUMN "projects"."code" IS 'Mã dự án, không được trùng (US_01)';

COMMENT ON COLUMN "projects"."end_date" IS 'Ngày kết thúc không trước ngày bắt đầu';

COMMENT ON COLUMN "projects"."manager_id" IS 'Quản lý dự án = người tạo';

COMMENT ON TABLE "project_members" IS 'Bảng nối nhiều-nhiều giữa dự án và nhân viên.';

COMMENT ON TABLE "tasks" IS 'Quá hạn và tiến độ 1/1 không lưu thành cột, tính ra mỗi lần hiển thị.';

COMMENT ON COLUMN "tasks"."assignee_id" IS 'Người làm task, phải là thành viên dự án (kiểm tra ở backend)';

COMMENT ON COLUMN "tasks"."created_by" IS 'Người tạo task';

COMMENT ON COLUMN "tasks"."due_date" IS 'Hạn chót, không sau projects.end_date (kiểm tra ở backend)';

COMMENT ON TABLE "task_comments" IS 'Không có updated_at và không có API sửa/xóa vì bình luận không được sửa hoặc xóa (US_08).';

ALTER TABLE "employees" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("user_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "employees" ADD FOREIGN KEY ("department_id") REFERENCES "departments" ("department_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "attendances" ADD FOREIGN KEY ("employee_id") REFERENCES "employees" ("employee_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Day_off_requests" ADD FOREIGN KEY ("employee_send_id") REFERENCES "employees" ("employee_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Day_off_requests" ADD FOREIGN KEY ("employee_receive_id") REFERENCES "employees" ("employee_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "projects" ADD FOREIGN KEY ("manager_id") REFERENCES "employees" ("employee_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "project_members" ADD FOREIGN KEY ("employee_id") REFERENCES "employees" ("employee_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "project_members" ADD FOREIGN KEY ("project_id") REFERENCES "projects" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tasks" ADD FOREIGN KEY ("project_id") REFERENCES "projects" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tasks" ADD FOREIGN KEY ("assignee_id") REFERENCES "employees" ("employee_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tasks" ADD FOREIGN KEY ("created_by") REFERENCES "employees" ("employee_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "task_comments" ADD FOREIGN KEY ("author_id") REFERENCES "employees" ("employee_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "task_comments" ADD FOREIGN KEY ("task_id") REFERENCES "tasks" ("id") DEFERRABLE INITIALLY IMMEDIATE;

